sp_widget.client_script:
api.controller = function($scope) {

    var c = this;


    c.raiseTicket = function() {

        window.location.href =
            "?id=raise_ticket";

    };

};

sp_widget.css:
.history-page {
    min-height: 100vh;
    background: #f3f6fa;

    padding: 35px;

    font-family: "Segoe UI", Arial, sans-serif;

    color: #102235;
}


.history-header {
    background: white;

    padding: 25px 30px;

    border-radius: 16px;

    border: 1px solid #dce4eb;

    margin-bottom: 25px;

    display: flex;
    justify-content: space-between;
    align-items: center;
}


.history-header h1 {
    margin: 0 0 7px;

    font-size: 29px;
}


.history-header p {
    margin: 0;

    color: #63768a;
}


.history-card {
    background: white;

    border-radius: 18px;

    border: 1px solid #dce4eb;

    padding: 20px;
}


.new-ticket-btn {
    border: none;

    background: #117f75;

    color: white;

    padding: 11px 18px;

    border-radius: 8px;

    font-weight: 700;

    cursor: pointer;
}


.ticket-item {
    display: flex;

    justify-content: space-between;

    align-items: center;

    padding: 20px;

    border-bottom: 1px solid #e5ebf0;
}


.ticket-item:last-child {
    border-bottom: none;
}


.ticket-number {
    font-size: 14px;

    color: #117f75;

    font-weight: 700;

    margin-bottom: 5px;
}


.ticket-subject {
    font-size: 17px;

    font-weight: 650;

    margin-bottom: 5px;
}


.ticket-date {
    font-size: 13px;

    color: #73869a;
}


.status {
    padding: 7px 13px;

    border-radius: 20px;

    font-size: 13px;

    font-weight: 700;
}


.status-open {
    background: #e7f1ff;
    color: #2767df;
}


.status-progress {
    background: #fff3d8;
    color: #a56a00;
}


.status-closed {
    background: #e5f7ed;
    color: #137442;
}


.empty-state {
    text-align: center;

    padding: 70px 20px;
}


.empty-icon {
    font-size: 45px;
}


.empty-state h2 {
    margin: 15px 0 8px;
}


.empty-state p {
    color: #708296;

    margin-bottom: 22px;
}


@media(max-width:600px) {

    .history-page {
        padding: 18px;
    }

    .history-header {
        flex-direction: column;

        align-items: flex-start;

        gap: 18px;
    }

    .ticket-item {
        align-items: flex-start;

        gap: 15px;

        flex-direction: column;
    }

}

sp_widget.script:
(function() {

    data.tickets = [];


    var gr = new GlideRecord("incident");


    gr.addQuery(
        "caller_id",
        gs.getUserID()
    );


    gr.orderByDesc("sys_created_on");

    gr.query();


    while (gr.next()) {

        var ticket = {};


        ticket.number =
            gr.getValue("number");


        ticket.subject =
            gr.getValue("short_description");


        ticket.date =
            gr.getDisplayValue("sys_created_on");


        var state =
            gr.getValue("state");


        if (state == "1") {

            ticket.status = "Open";

        } else if (state == "2") {

            ticket.status = "In Progress";

        } else {

            ticket.status = "Closed";

        }


        data.tickets.push(ticket);

    }

})();
